strategy("Operator typing probe", currency = currency.NONE, initial_capital = 1000000)
// DERIVED from visit_expr.py:1419,1477: matching line and label handles compare by identity.
var line a = line.new(0, close, 1, close)
line b = a
var label c = label.new(0, close, "x")
label d = c
plot(a == b ? 1 : 0)
plot(c != d ? 1 : 0)

if bar_index > 6 and bar_index % 7 == 3
    strategy.entry("L", strategy.long, qty = 1)
if bar_index > 6 and bar_index % 7 == 5
    strategy.close("L")

